from lib import *
S = SS('h29')
steps = [
    step("grpc-gateway(v2.31.0,用 protoc-gen-grpc-gateway 生成)把 REST 请求翻译成 gRPC 调用。POST /v1/echo 带 JSON 请求体,返回 HTTP 200 和 {\"id\":\"a\",\"name\":\"alice\",\"count\":\"123\",…};GET /v1/items/abc?name=bob:路径里的 id 和查询参数 name 都映射进请求消息,200;未知的查询参数 nope=1 被悄悄忽略,200;未知路径 404,{\"code\":5,\"message\":\"Not Found\",\"details\":[]};路径存在但方法不对(DELETE /v1/echo)返回的是 HTTP 501(code 12,“Method Not Allowed”),不是 405;非法 JSON 返回 400,message “unexpected EOF”。注意 int64 的 count 在 JSON 里是字符串 \"123\"。", t=tl(S(1)), done=lidx(S(1), 'POST 非法 JSON'), mark=lidx(S(1), 'POST /v1/echo'), b=bars([['映射成功(200)的请求数', 3, '3'], ['出错的请求数(404/501/400)', 3, '3']], 4, mark=[1], done=[0]), kv=KV([['路径参数 + 查询参数', '都映射进请求消息'], ['未知查询参数', '悄悄忽略'], ['DELETE 到只支持 POST 的路径', 'HTTP 501,不是 405']], ['DELETE 到只支持 POST 的路径'])),
    step("gRPC 状态码 → HTTP 状态码(服务端返回对应 code,访问 /v1/fail/{code}):Canceled → 499,Unknown → 500,InvalidArgument → 400,DeadlineExceeded → 504,NotFound → 404,AlreadyExists → 409,PermissionDenied → 403,ResourceExhausted → 429,FailedPrecondition → 400,Aborted → 409,OutOfRange → 400,Unimplemented → 501,Internal → 500,Unavailable → 503,DataLoss → 500,Unauthenticated → 401。这个映射是多对一的(400 对应三个 code,500 对应三个 code),REST 客户端从 HTTP 状态区分不了它们;响应体里的 code 字段是原始 gRPC code。服务端带的 details 会变成 JSON:[{\"@type\":\"type.googleapis.com/google.rpc.ErrorInfo\",\"reason\":\"BAD\",…}]。", t=tl(S(2)), done=lidx(S(2), 'Unauthenticated'), mark=lidx(S(2), 'Canceled'), b=bars([['gRPC code 个数(这里测了 16 个)', 16, '16'], ['它们映射到的不同 HTTP 状态个数', 11, '11']], 17, mark=[0], done=[1]), kv=KV([['400', 'InvalidArgument / FailedPrecondition / OutOfRange'], ['500', 'Unknown / Internal / DataLoss'], ['409', 'AlreadyExists / Aborted']], ['400'])),
    step("转换的体积与耗时(同一个 Item):payload 0 字节:protobuf 26 字节,JSON 响应体 85 字节(3.27 倍,JSON 里带着默认值字段 \"payload\":\"\",\"tags\":[],gateway 默认输出零值);100 字节:128 对 221(1.73 倍);100 KiB:102430 对 136621(1.33 倍,bytes 用 base64 编码膨胀约三分之一)。单次耗时中位数:小消息 直接 gRPC 68 µs、经 gateway 的 REST 146 µs(2.1 倍);100 KiB:246 µs 对 1220 µs(5.0 倍)。16 并发小消息吞吐:直接 gRPC 59336 请求/秒,经 gateway 的 REST 25095 请求/秒(2.4 倍)。这里的 REST 是 HTTP/1.1 的 Go net/http 客户端,所以差别包含了协议、JSON 编解码、多一跳转发三部分,不能全归因于“JSON”。", t=tl(S(3)), done=lidx(S(3), '16 个并发'), mark=lidx(S(3), 'payload      0 字节'), b=bars([['小消息:直接 gRPC 单次 µs', 68, '68'], ['小消息:经 gateway 单次 µs', 146, '146'], ['100 KiB:直接 gRPC 单次 µs', 246, '246'], ['100 KiB:经 gateway 单次 µs', 1220, '1220']], 1300, mark=[1, 3], done=[0, 2]), kv=KV([['体积(小消息)', '26 → 85 字节(3.27 倍)'], ['单次耗时(100 KiB)', '246 → 1220 µs(5.0 倍)'], ['16 并发吞吐', '59336 → 25095 请求/秒']], ['单次耗时(100 KiB)'])),
    step("HTTP 头 → gRPC metadata:发送 Authorization、X-Custom、Grpc-Metadata-Foo 三个头。默认情况下,后端看到的 metadata 里有:authorization(转发了),foo(Grpc-Metadata- 前缀的头去掉前缀转发),grpcgateway-authorization、grpcgateway-user-agent(gateway 额外加的带 grpcgateway- 前缀的原始头),x-forwarded-for、x-forwarded-host;没有 x-custom——自定义头默认不转发。用 runtime.WithIncomingHeaderMatcher 放行 X-Custom 后,后端看到 x-custom=c1。所以新增的业务头(租户、追踪 ID)要在 gateway 配置里明确放行。", t=tl(S(4)), done=lidx(S(4), 'WithIncomingHeaderMatcher 放行'), mark=lidx(S(4), '默认:'), b=bars([['默认转发的我们发的 3 个头里', 2, '2(authorization、foo)'], ['放行 X-Custom 之后', 3, '3']], 4, mark=[0], done=[1]), kv=KV([['Authorization', '默认转发'], ['Grpc-Metadata-Foo', '去掉前缀后转发为 foo'], ['X-Custom', '默认不转发,要 HeaderMatcher']], ['X-Custom'])),
    step("超时与取消:HTTP 客户端 100 ms 就放弃(后端要 2000 ms),102.1 ms 后返回错误;后端 handler 的 ctx 被取消(结果 “canceled”)——客户端断开会一路传到 gRPC 后端。请求头 Grpc-Timeout: 300m(300 毫秒)时,gateway 把它变成 gRPC 的 deadline:HTTP 504,303.2 ms 后返回,响应体 {\"code\":4,\"message\":\"context deadline exceeded\"}。所以 HTTP 侧的超时可以通过 Grpc-Timeout 头或客户端断开传到后端(第 33 篇讲超时叠加)。", t=tl(S(5)), done=lidx(S(5), 'Grpc-Timeout: 300m'), mark=lidx(S(5), 'HTTP 客户端超时'), b=bars([['HTTP 客户端放弃的时刻 ms', 102.1, '102.1'], ['Grpc-Timeout: 300m 返回的时刻 ms', 303.2, '303.2']], 320, mark=[0], done=[1]), kv=KV([['客户端断开', '后端 ctx 被取消'], ['Grpc-Timeout: 300m', 'HTTP 504,303.2 ms'], ['响应体', 'code 4 = DeadlineExceeded']], ['客户端断开'])),
    step("服务端流 → HTTP:GET /v1/count?n=3 返回 HTTP 200,响应体共 3 行,每行是一个 JSON 对象,外面包了一层 result:{\"result\":{\"id\":\"0\",…}}。每条流消息变成一行(分块传输)。浏览器里可以边收边读,但这不是 gRPC 流的完整等价——没有客户端流和双向流(gateway 默认只支持服务端流)。", t=tl(S(6)), done=lidx(S(6), '"id":"2"'), mark=lidx(S(6), '"id":"0"'), b=bars([['流里的消息数 → 响应体行数', 3, '3 行']], 4, mark=[0], done=[0]), kv=KV([['服务端流', '每条消息一行 JSON,外面包 result'], ['传输', '分块'], ['限制', '没有客户端流/双向流']], ['限制'])),
]
A = mkarth('h29', 29, 'gRPC,grpc-gateway,REST,JSON 转码,状态码映射,Go,真实验证,动画演示',
    '实测 grpc-gateway v2.31.0:路径与查询参数映射、gRPC 状态码到 HTTP 状态码的多对一映射、JSON 体积是 protobuf 的 1.3 到 3.3 倍、经 gateway 的耗时是直连 gRPC 的 2 到 5 倍、自定义头默认不转发、客户端断开会取消后端、服务端流变成 JSON 行。',
    '把 gRPC 服务暴露成 REST,中间那层 grpc-gateway 到底做了什么、花多少?错误码怎么翻译、头怎么传、超时和流怎么办?这篇用真实生成的 gateway 代码跑了一遍。',
    [('11 种 HTTP 状态', '16 个 gRPC 状态码被 gateway 映射成 11 种不同的 HTTP 状态,多对一'), ('5.0 倍', '100 KiB 消息经 gateway 的 REST 相比直连 gRPC 的单次耗时倍数'), ('x-custom 默认被丢掉', '自定义 HTTP 头要用 WithIncomingHeaderMatcher 放行才会转成 metadata')],
    [('它是什么', '<p>从带 google.api.http 注解的 .proto 生成的反向代理:HTTP/JSON 请求进来,转成 gRPC 调用转发给后端,再把响应转回 JSON。</p>'),
     ('状态码映射', '<p>gRPC 的 16 种错误码映射到 HTTP 状态,是多对一的(400、500、409 各对应多个),响应体里保留原始的 code、message 和 details。</p>'),
     ('成本', '<p>JSON 比 protobuf 大(gateway 默认还输出零值字段,bytes 用 base64),多一跳转发加上 JSON 编解码,单次耗时和吞吐都不如直连 gRPC。本机上 HTTP/1.1 的 REST 客户端与 gRPC 的差别包含协议的差别。</p>'),
     ('头与 metadata', '<p>Authorization 和 Grpc-Metadata- 前缀的头会被转发,其它自定义头默认不转发。</p>'),
     ('超时与取消', '<p>HTTP 客户端断开会取消后端的调用;Grpc-Timeout 头可以设置后端的 deadline。</p>'),
     ('流', '<p>服务端流变成逐行 JSON(每行包一层 result)。客户端流和双向流默认不支持。</p>')],
    steps,
    [ENV_H + '。本篇用 grpc-gateway v2.31.0(runtime 与 protoc-gen-grpc-gateway 都是这个版本),为此 go.mod 里 golang.org/x/net 升到 v0.59.0,genproto 等也相应升级(前面的文章用的是 x/net v0.57.0);google/api 的两个 .proto 是我按公开定义手写进 protoc 的 include 目录的最小版本;HTTP 侧用 Go 的 net/http(HTTP/1.1 keep-alive);耗时与吞吐是本机回环、同进程内的测量',
     '没有验证:OpenAPI 文档生成(protoc-gen-openapiv2);自定义 JSON 序列化选项(UseProtoNames、EmitUnpopulated 关闭);更复杂的路径模板与 body 绑定;双向流经 WebSocket 的转发;鉴权中间件与 gateway 的搭配;gateway 与后端分开部署时多出的网络跳数;其它语言的 gateway(如 Envoy 的 gRPC-JSON transcoder)的行为'],
    'gRPC-Gateway')
